1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInUseException;
8	
9	/**
10	 * Rejects a create request whose normalized telephone is already used by any other owner.
11	 * Runs after {@link ValidateOwnerFields} has normalized the telephone to digits, and
12	 * before {@link BuildOwner}, so a duplicate is a 409 rather than a persisted record.
13	 */
14	public class CheckOwnerTelephoneUnique {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws OwnerTelephoneInUseException {
18	        String telephone = normalize(request.getTelephone());
19	        if (telephone == null) {
20	            return;
21	        }
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(normalize(existing.getTelephone()))) {
24	                throw new OwnerTelephoneInUseException(request.getTelephone());
25	            }
26	        }
27	    }
28	
29	    private static String normalize(String telephone) {
30	        if (telephone == null) {
31	            return null;
32	        }
33	        String digits = telephone.replaceAll("\\D", "");
34	        return digits.isEmpty() ? null : digits;
35	    }
